      }).position(0, -0.07, 0)
    )
    .add(
      primitives.cylinder({
        name: "platform top",
        size: [5.0, 0.02, 5.0],
        material: material.physical({ color: "#0b0c10", metallic: 0.5, roughness: 0.12, clearcoat: 1, clearcoatRoughness: 0.03, envMapIntensity: 1.4 }),
        receiveShadow: true
      }).position(0, -0.011, 0)
    )
    .add(
      primitives.cylinder({
        name: "platform chrome edge",
