        material: chrome
      }).position(0, -0.02, 0)
    )
    .add(carGroup)
    .add(effects.screenSpaceReflections({ intensity: 0.5 } as never))
    .add(effects.bloom({ intensity: 0.35, threshold: 0.9, radius: 0.5 }))
    .camera(camera.perspective({ position: [4.6, 1.55, 5.0], target: [0, 0.55, 0], fov: 34 }))
